write: {"content": "import csv

def main():
    russia = 0
    foreign = 0
    with open('компоненты.csv', newline='', encoding='utf-8') as f:
        reader = csv.reader(f, delimiter=';')
        next(reader, None)  # пропускаем заголовок
        for row in reader:
            if len(row) < 3:
                continue
            country = row[2].strip()
            if country == 'Россия':
                russia += 1
            else:
                foreign += 1

    total = russia + foreign
    percent_foreign = round((foreign / total) * 100) if total else 0

    print(f'Россия — {russia}')
    print(f'Иностранные — {foreign}')
    print(f'Доля иностранных — {percent_foreign}%')

if __name__ == '__main__':
    main()
